B.ahG=s(["Jugador {0}","Joueur {0}","Spieler {0}","Jogador {0}","\u30d7\u30ec\u30a4\u30e4\u30fc{0}","\u0916\u093f\u0932\u093e\u0921\u093c\u0940 {0}","Pemain {0}","Ng\u01b0\u1eddi ch\u01a1i {0}"],t.s)
